import { join } from 'node:path';
import { FakeAdapter } from '@webdcc/fake-adapter';
import type { AdapterEvent, AgentId } from '@webdcc/protocol';
import { openDb } from '../../src/db.js';
import { Store } from '../../src/store.js';
import { SessionManager } from '../../src/manager.js';
const directory = process.argv[2]!; const agent = (process.argv[3] ?? 'claude-code') as AgentId;
const db = openDb(join(directory, 'source.sqlite')); const store = new Store(db);
const manager = new SessionManager(store, { idleDisposeMin: 0 }); const adapter = new FakeAdapter({ id: agent });
let callback!: (id: string, event: AdapterEvent) => void; adapter.onEvent = cb => { callback = cb; }; adapter.send = async () => undefined; manager.registerAdapter(adapter);
const workspace = store.createWorkspace('hot crash', directory); const session = await manager.createSession({ workspaceId: workspace.id, agent });
const sent = await manager.send(session.id, { text: 'original input' });
callback(session.id, { type: 'item.start', itemKey: 'hot', kind: 'assistant.message', data: { text: '' } });
callback(session.id, { type: 'item.delta', itemKey: 'hot', field: 'text', append: 'original partial\n' });
callback(session.id, { type: 'item.start', itemKey: 'command', kind: 'command', data: { command: 'original native command', status: 'running', outputTail: '' } });
callback(session.id, { type: 'item.delta', itemKey: 'command', field: 'output', append: 'original native output\n' });
callback(session.id, { type: 'item.start', itemKey: 'thinking', kind: 'reasoning', data: { text: 'original reasoning' } });
callback(session.id, { type: 'item.start', scope: 'session', itemKey: 'global', kind: 'assistant.message', data: { text: 'original session output' } });
const queued = await manager.send(session.id, { text: 'keep queued' });
process.send?.({ sessionId: session.id, publicTurnId: sent.turnId, queuedTurnId: queued.turnId, rawId: store.nativeEvents.list(session.id, 0, 500).at(-1)!.id }); setInterval(() => undefined, 1000);
